# app.py
import textwrap
from collections import Counter
from pathlib import Path
from tempfile import NamedTemporaryFile

import viktor as vkt
from viktor import UserError

import ifcopenshell
import ifcopenshell.api


def _get_uploaded_ifc_file(params):
    file_field = params.page_1.tab_1.inputs.ifc_file
    if not file_field:
        return None
    return file_field.file


def _write_uploaded_ifc_to_temp(ifc_file: vkt.File) -> Path:
    try:
        content = ifc_file.getvalue()
    except Exception as e:
        raise UserError(f"Could not read uploaded file contents: {e}")

    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
        tmp.write(content)
        return Path(tmp.name)


def _load_model(params) -> ifcopenshell.file:
    ifc_file = _get_uploaded_ifc_file(params)
    if ifc_file is None:
        raise UserError("Please upload an IFC file first.")

    tmp_path = _write_uploaded_ifc_to_temp(ifc_file)
    try:
        return ifcopenshell.open(str(tmp_path))
    except Exception as e:
        raise UserError(f"Failed to open IFC file: {e}")


def _iter_property_sets(element):
    """Yield IfcPropertySet objects attached to the element."""
    for rel in getattr(element, "IsDefinedBy", []) or []:
        if not rel or not rel.is_a("IfcRelDefinesByProperties"):
            continue
        pdef = rel.RelatingPropertyDefinition
        if pdef and pdef.is_a("IfcPropertySet"):
            yield pdef


def _get_target_elements(model, ifc_class: str, limit: int):
    if ifc_class == "IfcElement (all)":
        elems = list(model.by_type("IfcElement"))
    else:
        elems = list(model.by_type(ifc_class))

    if limit and limit > 0:
        elems = elems[: int(limit)]
    return elems


def _parse_new_value(params):
    if params.page_1.tab_1.inputs.clear_value:
        # IfcOpenShell's pset.edit_pset typically interprets None as "remove property".
        return None

    raw = (params.page_1.tab_1.inputs.new_value or "").strip()
    vtype = params.page_1.tab_1.inputs.value_type

    if vtype == "String":
        return raw

    if vtype == "Number":
        if raw == "":
            return None
        try:
            return float(raw)
        except ValueError:
            raise UserError("Value type is 'Number' but the provided value cannot be parsed as a float.")

    if vtype == "Boolean":
        if raw.lower() in {"true", "t", "yes", "y", "1"}:
            return True
        if raw.lower() in {"false", "f", "no", "n", "0"}:
            return False
        raise UserError("Value type is 'Boolean'. Use true/false (or yes/no, 1/0).")

    raise UserError("Unsupported value type.")


def _get_property_name(params) -> str:
    manual = (params.page_1.tab_1.inputs.property_name_manual or "").strip()
    if manual:
        return manual

    selected = params.page_1.tab_1.inputs.property_name
    if not selected:
        raise UserError("Please select a property (or type a property name).")
    return str(selected)


def _get_pset_scope(params) -> str:
    return params.page_1.tab_1.inputs.pset_scope or "Any"


def _collect_pset_names(elements, scan_limit: int = 500):
    names = set()
    for idx, el in enumerate(elements):
        if scan_limit and idx >= scan_limit:
            break
        for pset in _iter_property_sets(el):
            if pset.Name:
                names.add(pset.Name)
    return sorted(names)


def _collect_property_counts(elements, pset_scope: str, scan_limit: int = 500):
    counter = Counter()
    for idx, el in enumerate(elements):
        if scan_limit and idx >= scan_limit:
            break
        for pset in _iter_property_sets(el):
            if pset_scope != "Any" and pset.Name != pset_scope:
                continue
            for prop in getattr(pset, "HasProperties", []) or []:
                if getattr(prop, "Name", None):
                    counter[prop.Name] += 1
    return counter


def _apply_batch_update(model, elements, property_name: str, new_value, pset_scope: str,
                        create_missing: bool, pset_to_create: str):
    updated_element_ids = set()
    edited_pset_count = 0
    created_psets = 0

    for el in elements:
        found_on_element = False

        # Update all matching psets on this element
        for pset in _iter_property_sets(el):
            if pset_scope != "Any" and pset.Name != pset_scope:
                continue

            has_prop = any(getattr(p, "Name", None) == property_name for p in (pset.HasProperties or []))
            if not has_prop:
                continue

            ifcopenshell.api.run(
                "pset.edit_pset",
                model,
                pset=pset,
                properties={property_name: new_value},
            )
            edited_pset_count += 1
            found_on_element = True
            updated_element_ids.add(el.id())

        # Optionally create the property on this element if it doesn't exist
        if create_missing and not found_on_element:
            if not pset_to_create:
                raise UserError(
                    "Create-missing is enabled, but no Pset name is provided for newly created properties."
                )

            existing = None
            for pset in _iter_property_sets(el):
                if pset.Name == pset_to_create:
                    existing = pset
                    break

            if existing is None:
                existing = ifcopenshell.api.run("pset.add_pset", model, product=el, name=pset_to_create)
                created_psets += 1

            ifcopenshell.api.run(
                "pset.edit_pset",
                model,
                pset=existing,
                properties={property_name: new_value},
            )
            edited_pset_count += 1
            updated_element_ids.add(el.id())

    return {
        "elements_considered": len(elements),
        "elements_updated": len(updated_element_ids),
        "psets_edited": edited_pset_count,
        "psets_created": created_psets,
    }


def _create_updated_ifc_file_and_stats(params):
    model = _load_model(params)

    ifc_class = params.page_1.tab_1.inputs.element_type or "IfcElement (all)"
    update_limit = int(params.page_1.tab_1.inputs.update_limit or 0)

    elements = _get_target_elements(model, ifc_class=ifc_class, limit=update_limit)

    property_name = _get_property_name(params)
    new_value = _parse_new_value(params)
    pset_scope = _get_pset_scope(params)

    create_missing = bool(params.page_1.tab_1.inputs.create_missing)
    pset_to_create = (params.page_1.tab_1.inputs.pset_to_create or "").strip()

    stats = _apply_batch_update(
        model,
        elements,
        property_name=property_name,
        new_value=new_value,
        pset_scope=pset_scope,
        create_missing=create_missing,
        pset_to_create=pset_to_create,
    )

    # Write updated IFC to a temporary file
    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp_out:
        out_path = Path(tmp_out.name)

    model.write(str(out_path))
    return vkt.File.from_path(out_path), stats


def _get_ifc_class_options(params, **kwargs):
    ifc_file = _get_uploaded_ifc_file(params)
    if ifc_file is None:
        return ["IfcElement (all)"]

    try:
        model = _load_model(params)
    except UserError:
        return ["IfcElement (all)"]

    classes = sorted({el.is_a() for el in model.by_type("IfcElement")})
    return ["IfcElement (all)"] + classes


def _get_pset_options(params, **kwargs):
    ifc_file = _get_uploaded_ifc_file(params)
    if ifc_file is None:
        return ["Any"]

    try:
        model = _load_model(params)
    except UserError:
        return ["Any"]

    ifc_class = params.page_1.tab_1.inputs.element_type or "IfcElement (all)"
    scan_limit = int(params.page_1.tab_1.inputs.scan_limit or 500)
    elements = _get_target_elements(model, ifc_class=ifc_class, limit=scan_limit)

    pset_names = _collect_pset_names(elements, scan_limit=scan_limit)
    return ["Any"] + pset_names


def _get_property_options(params, **kwargs):
    ifc_file = _get_uploaded_ifc_file(params)
    if ifc_file is None:
        return []

    try:
        model = _load_model(params)
    except UserError:
        return []

    ifc_class = params.page_1.tab_1.inputs.element_type or "IfcElement (all)"
    scan_limit = int(params.page_1.tab_1.inputs.scan_limit or 500)
    elements = _get_target_elements(model, ifc_class=ifc_class, limit=scan_limit)

    pset_scope = _get_pset_scope(params)
    counts = _collect_property_counts(elements, pset_scope=pset_scope, scan_limit=scan_limit)

    # Sort by frequency (desc), then alphabetically
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0].lower()))

    # Use labels with counts for UX; the returned value is just the property name
    return [vkt.OptionListElement(value=name, label=f"{name} (in {cnt} scanned elements)") for name, cnt in items]


class Parametrization(vkt.Parametrization):
    page_1 = vkt.Page("1. Upload & Select", views=["original_ifc_view", "property_overview"])  # no orphan fields
    page_1.tab_1 = vkt.Tab("Inputs")
    page_1.tab_1.inputs = vkt.Section("Global property update")
    page_1.tab_1.inputs.intro = vkt.Text(textwrap.dedent("""\
        # Global Property Editor (IFC)

        Upload an IFC file, pick a property (e.g. **Phase** / **Status**) and a new value,
        then preview and download a modified IFC with that property updated in bulk.

        Notes:
        - This app updates **IfcPropertySet** properties (psets).
        - If the property exists on multiple psets for an element, it updates all matches within the selected **Pset scope**.
    """))

    page_1.tab_1.inputs.ifc_file = vkt.FileField("IFC file")

    page_1.tab_1.inputs.element_type = vkt.OptionField(
        "Element type to update",
        options=_get_ifc_class_options,
        default="IfcElement (all)",
        description="Choose a specific IFC class (e.g. IfcWall) or update all IfcElement instances.",
    )

    page_1.tab_1.inputs.scan_limit = vkt.NumberField(
        "Scan limit for options (0 = all)",
        default=500,
        min=0,
        step=1,
        description="Used only to build dropdown options (property/pset lists).",
    )

    page_1.tab_1.inputs.update_limit = vkt.NumberField(
        "Update limit (0 = all)",
        default=0,
        min=0,
        step=1,
        description="Safety limiter for batch editing. Set 0 to update all matching elements.",
    )

    page_1.tab_1.inputs.pset_scope = vkt.OptionField(
        "Pset scope",
        options=_get_pset_options,
        default="Any",
        description="Filter where to look for the property (Any = match in all psets).",
    )

    page_1.tab_1.inputs.property_name = vkt.OptionField(
        "Property (from IFC)",
        options=_get_property_options,
        description="Select a property discovered in the scanned elements.",
    )

    page_1.tab_1.inputs.property_name_manual = vkt.TextField(
        "Or type a property name (overrides selection)",
        default="",
    )

    page_1.tab_1.inputs.new_value = vkt.TextField("New value", default="Construction")

    page_1.tab_1.inputs.value_type = vkt.OptionField(
        "Value type",
        options=["String", "Number", "Boolean"],
        default="String",
        variant="radio-inline",
    )

    page_1.tab_1.inputs.clear_value = vkt.BooleanField(
        "Clear / remove property value",
        default=False,
        description="Attempts to remove the property value (sets it to None).",
    )

    page_1.tab_1.inputs.create_missing = vkt.BooleanField(
        "Create property if missing on an element",
        default=True,
        description="If the property is not present on an element, create it under the Pset name below.",
    )

    page_1.tab_1.inputs.pset_to_create = vkt.TextField(
        "Pset name for created properties",
        default="Pset_Global",
        visible=vkt.Lookup("page_1.tab_1.inputs.create_missing"),
    )

    page_2 = vkt.Page("2. Preview & Export", views=["updated_ifc_and_data"])  # no orphan fields
    page_2.tab_1 = vkt.Tab("Export")
    page_2.tab_1.actions = vkt.Section("Download")
    page_2.tab_1.actions.note = vkt.Text(textwrap.dedent("""\
        Click the button to generate and download a modified IFC.

        Tip: Keep **Update limit** at 0 to update all elements of the selected type.
    """))
    page_2.tab_1.actions.download_btn = vkt.DownloadButton(
        "Download updated IFC",
        method="download_updated_ifc",
        longpoll=True,
    )


class Controller(vkt.Controller):
    label = "Global Property Editor"
    parametrization = Parametrization(width=60)

    @vkt.IFCView("Original IFC")
    def original_ifc_view(self, params, **kwargs):
        ifc_file = _get_uploaded_ifc_file(params)
        if ifc_file is None:
            raise UserError("Please upload an IFC file to view it.")
        return vkt.IFCResult(ifc_file)

    @vkt.TableView("Available properties (overview)")
    def property_overview(self, params, **kwargs):
        if _get_uploaded_ifc_file(params) is None:
            return vkt.TableResult(
                [["Upload an IFC file to list properties.", ""]],
                column_headers=["Info", ""],
            )

        model = _load_model(params)

        ifc_class = params.page_1.tab_1.inputs.element_type or "IfcElement (all)"
        scan_limit = int(params.page_1.tab_1.inputs.scan_limit or 500)
        elements = _get_target_elements(model, ifc_class=ifc_class, limit=scan_limit)

        pset_scope = _get_pset_scope(params)
        counts = _collect_property_counts(elements, pset_scope=pset_scope, scan_limit=scan_limit)

        rows = [[name, cnt] for name, cnt in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0].lower()))]
        return vkt.TableResult(
            rows,
            column_headers=["Property name", "Occurrences in scanned elements"],
        )

    @vkt.IFCAndDataView("Updated IFC (preview)", x_axis_to_right=True)
    def updated_ifc_and_data(self, params, **kwargs):
        updated_ifc, stats = _create_updated_ifc_file_and_stats(params)

        data = vkt.DataGroup(
            vkt.DataItem("Elements considered", stats["elements_considered"]),
            vkt.DataItem("Elements updated", stats["elements_updated"]),
            vkt.DataItem("Psets edited", stats["psets_edited"]),
            vkt.DataItem("Psets created", stats["psets_created"]),
        )
        return vkt.IFCAndDataResult(ifc=updated_ifc, data=data)

    def download_updated_ifc(self, params, **kwargs):
        updated_ifc, _stats = _create_updated_ifc_file_and_stats(params)

        original = _get_uploaded_ifc_file(params)
        original_name = getattr(original, "name", None) or "model.ifc"
        file_name = f"updated_{Path(str(original_name)).stem}.ifc"
        return vkt.DownloadResult(updated_ifc, file_name)
